 void Update(){if(Input.GetKeyDown(KeyCode.F12))Capture(Path.Combine(Application.persistentDataPath,"screenshot.png"));if(inGame&&!modal&&Input.GetKeyDown(KeyCode.Space))Play();if(Input.GetKeyDown(KeyCode.Escape)){if(modal)CloseModal();else if(inGame)ShowMenu();}if(inGame&&!modal&&Input.GetKeyDown(KeyCode.Z))Undo();if(boat){float bob=Mathf.Sin(Time.unscaledTime*1.2f)*3;boat.anchoredPosition=new Vector2(boatX,-350+bob);}if(!playing)return;elapsed+=Time.unscaledDeltaTime;if(elapsed<.7f)return;elapsed-=.7f;beat++;if(beat>=8){playing=false;beat=-1;playLabel.text="听一圈";UpdateSlots();if(!freeMode&&board.Matches(Content.Levels[level]))Complete();else if(!freeMode)SetFeedback("景物还没有完全回应。比较长短、位置与留白，或点“再看仔细些”。");else SetFeedback("这一圈结束了。可以继续修改，或保存短曲。");return;}Sound(board.cells[beat]);for(int i=0;i<8;i++)markers[i].color=i==beat?new Color(.85f,.69f,.38f):new Color(.95f,.94f,.87f,.8f);if(!board.cells[beat].Empty){StartCoroutine(Ripple(115+beat*119,460,tones[board.cells[beat].tone]));if(Content.Levels[level].chapter==0&&board.cells[beat].tone==Content.Levels[level].target[beat].tone&&board.cells[beat].rank==Content.Levels[level].target[beat].rank)boatX=Mathf.Min(930,boatX+(board.cells[beat].rank==2?55:25));}UpdateSlots();}
