 public void Capture(string path){Canvas.ForceUpdateCanvases();var camera=Camera.main;var old=camera.targetTexture;var rt=RenderTexture.GetTemporary(1600,900,24);camera.targetTexture=rt;camera.Render();var previous=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(1600,900,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1600,900),0,0);t.Apply();File.WriteAllBytes(path,t.EncodeToPNG());Destroy(t);camera.targetTexture=old;RenderTexture.active=previous;RenderTexture.ReleaseTemporary(rt);}
 void ClickSlotForTest(int index){Canvas.ForceUpdateCanvases();var pos=RectTransformUtility.WorldToScreenPoint(canvas.worldCamera,slotImages[index].rectTransform.TransformPoint(slotImages[index].rectTransform.rect.center));var e=new PointerEventData(EventSystem.current){position=pos};var hits=new System.Collections.Generic.List<RaycastResult>();EventSystem.current.RaycastAll(e,hits);var hit=hits.Select(h=>h.gameObject.GetComponentInParent<SlotInput>()).FirstOrDefault(h=>h!=null);if(hit==null||hit.index!=index)throw new Exception("UI raycast missed slot "+index);ExecuteEvents.Execute(hit.gameObject,e,ExecuteEvents.pointerClickHandler);}
 IEnumerator SelfTest(){var dir=Path.Combine(Application.dataPath,"../Validation");Directory.CreateDirectory(dir);yield return new WaitForSeconds(1);Capture(Path.Combine(dir,"00-menu.png"));yield return new WaitForSeconds(.5f);int passed=0;for(int n=0;n<9;n++){LoadLevel(n);yield return null;var l=Content.Levels[n];int mass=board.Mass; if(n==0){Canvas.ForceUpdateCanvases();var src=RectTransformUtility.WorldToScreenPoint(canvas.worldCamera,slotImages[8].rectTransform.TransformPoint(slotImages[8].rectTransform.rect.center));var dst=RectTransformUtility.WorldToScreenPoint(canvas.worldCamera,slotImages[0].rectTransform.TransformPoint(slotImages[0].rectTransform.rect.center));BeginDrag(8,src);DragAt(dst);EndDrag(new PointerEventData(EventSystem.current){position=dst});if(board.cells[0].Empty||!board.cells[8].Empty)throw new Exception("Drag move failed");Undo();} // Drive the same selection path used by clicks, including every required merge.
 for(int i=0;i<8;i++){var t=l.target[i];if(t.Empty)continue;for(int count=0;count<t.Mass;count++){int from=Array.FindIndex(board.cells,8,8,s=>!s.Empty&&s.tone==t.tone);if(from<0)throw new Exception("Missing source stone");ClickSlotForTest(from);ClickSlotForTest(i);}}
 if(board.Mass!=mass||!board.Matches(l))throw new Exception("Puzzle failed "+n);if(n==1){selected=0;SplitSelected();Undo();if(!board.Matches(l))throw new Exception("Split undo failed");}
 Persist();var read=JsonUtility.FromJson<SaveData>(File.ReadAllText(savePath));if(read.cells.Length!=16||read.level!=n)throw new Exception("Save reload failed");Play();yield return new WaitForSeconds(1.3f);Capture(Path.Combine(dir,"level-"+n+".png"));yield return new WaitForSeconds(5.3f);if(!solved)throw new Exception("Runtime completion failed "+n);passed++;if(n%3==2)Capture(Path.Combine(dir,"poem-"+n+".png"));CloseModal();}
 StartFree();yield return new WaitForSeconds(.5f);save.composition=(Stone[])board.cells.Clone();Persist();File.WriteAllText(Path.Combine(dir,"runtime-results.json"),"{\"passedLevels\":"+passed+",\"saveRoundTrips\":9,\"splitUndo\":true,\"completed\":true}");Debug.Log("CIJING_RUNTIME_PASS 9 levels, save, split undo");yield return new WaitForSeconds(1);Application.Quit();}
}
public sealed class BoatGraphic:MaskableGraphic {
 protected override void OnPopulateMesh(VertexHelper v){v.Clear();Color32 c=color;Add(v,new Vector2(0,20),new Vector2(145,20),new Vector2(115,0),c);Add(v,new Vector2(0,20),new Vector2(115,0),new Vector2(30,0),c);Add(v,new Vector2(55,22),new Vector2(100,22),new Vector2(75,45),c);}
 void Add(VertexHelper v,Vector2 a,Vector2 b,Vector2 c,Color32 col){int n=v.currentVertCount;v.AddVert(a,col,Vector2.zero);v.AddVert(b,col,Vector2.zero);v.AddVert(c,col,Vector2.zero);v.AddTriangle(n,n+1,n+2);}
}
